// EmailServiceServer is the server API for EmailService service.
// All implementations must embed UnimplementedEmailServiceServer
// for forward compatibility.
//
// EmailService owns correspondence with customers: what was composed, who it
// went to, and what happened to each copy.
//
// The unit is one message per recipient, never one message with a list of
// addresses. That single decision is what makes four requirements possible at
// once - recipients cannot see each other, each mail is personalised, each is
// retried on its own, and each carries its own delivery status.
type EmailServiceServer interface {
	ListCampaigns(context.Context, *ListCampaignsRequest) (*ListCampaignsResponse, error)
	GetCampaign(context.Context, *GetCampaignRequest) (*GetCampaignResponse, error)
	// Render as one chosen recipient will receive it. Required before sending:
	// a variable that cannot resolve is only obvious when somebody sees the
	// gap where the name should be.
	PreviewCampaign(context.Context, *PreviewCampaignRequest) (*PreviewCampaignResponse, error)
	CreateCampaign(context.Context, *CreateCampaignRequest) (*CreateCampaignResponse, error)
	// Sends a factory RFQ through the configured procurement shared mailbox.
	// The gateway supplies the configured employee id; browsers cannot choose
	// an arbitrary colleague as sender.
	SendProcurementRfq(context.Context, *SendProcurementRfqRequest) (*SendProcurementRfqResponse, error)
	SendProcurementOrder(context.Context, *SendProcurementOrderRequest) (*SendProcurementOrderResponse, error)
	// The per-recipient list. Also the failed-delivery queue, filtered.
	ListMessages(context.Context, *ListMessagesRequest) (*ListMessagesResponse, error)
	GetMessage(context.Context, *GetMessageRequest) (*GetMessageResponse, error)
	// Put a failed message back, optionally at a corrected address.
	RequeueMessage(context.Context, *RequeueMessageRequest) (*RequeueMessageResponse, error)
	// Close a failed message without sending it. Requires a reason.
	AbandonMessage(context.Context, *AbandonMessageRequest) (*AbandonMessageResponse, error)
	// Drafts. Personal by construction - every one of these is scoped to the
	// caller and no data scope widens it. A draft is unfinished thinking, not
	// correspondence: nobody has said it yet.
	SaveDraft(context.Context, *SaveDraftRequest) (*SaveDraftResponse, error)
	ListDrafts(context.Context, *ListDraftsRequest) (*ListDraftsResponse, error)
	GetDraft(context.Context, *GetDraftRequest) (*GetDraftResponse, error)
	DeleteDraft(context.Context, *DeleteDraftRequest) (*DeleteDraftResponse, error)
	// Promote a draft into a real send. Runs the ordinary create path, so the
	// draft only disappears once the mail is queued.
	SendDraft(context.Context, *SendDraftRequest) (*SendDraftResponse, error)
	// Timed delivery. A scheduled send is already queued - the hold is a column
	// the worker respects - so these three are about the window before it goes:
	// what is waiting, let one go early, and stop one that has not gone.
	ListScheduled(context.Context, *ListScheduledRequest) (*ListScheduledResponse, error)
	SendScheduledNow(context.Context, *SendScheduledNowRequest) (*SendScheduledNowResponse, error)
	// Cancelling returns the mail to the drafts folder rather than binning it:
	// somebody who calls a send back usually means to change it, not lose it.
	CancelScheduled(context.Context, *CancelScheduledRequest) (*CancelScheduledResponse, error)
	ListSignatures(context.Context, *ListSignaturesRequest) (*ListSignaturesResponse, error)
	CreateSignature(context.Context, *CreateSignatureRequest) (*CreateSignatureResponse, error)
	UpdateSignature(context.Context, *UpdateSignatureRequest) (*UpdateSignatureResponse, error)
	DeleteSignature(context.Context, *DeleteSignatureRequest) (*DeleteSignatureResponse, error)
	// The template library (C5): reusable phrases with {{variables}} from the
	// same vocabulary campaigns render with, applied in one click at compose.
	ListEmailTemplates(context.Context, *ListEmailTemplatesRequest) (*ListEmailTemplatesResponse, error)
	CreateEmailTemplate(context.Context, *CreateEmailTemplateRequest) (*CreateEmailTemplateResponse, error)
	UpdateEmailTemplate(context.Context, *UpdateEmailTemplateRequest) (*UpdateEmailTemplateResponse, error)
	DeleteEmailTemplate(context.Context, *DeleteEmailTemplateRequest) (*DeleteEmailTemplateResponse, error)
	// Files travelling with a send, and pictures embedded inside one.
	//
	// Bytes go browser-to-bucket through the presigned URL and never occupy
	// the gateway; only metadata passes through here. The size the client
	// reports afterwards is never trusted - Register reads the real one back
	// out of storage, because a cap checked against a claim is not a cap.
	PresignAttachment(context.Context, *PresignAttachmentRequest) (*PresignAttachmentResponse, error)
	RegisterAttachment(context.Context, *RegisterAttachmentRequest) (*RegisterAttachmentResponse, error)
	ListAttachments(context.Context, *ListAttachmentsRequest) (*ListAttachmentsResponse, error)
	PresignImage(context.Context, *PresignImageRequest) (*PresignImageResponse, error)
	RegisterImage(context.Context, *RegisterImageRequest) (*RegisterImageResponse, error)
	ImportImage(context.Context, *ImportImageRequest) (*ImportImageResponse, error)
	// Serves the public, token-addressed image route. Bounded by the 2 MB cap,
	// so one unary response is fine and streaming would be ceremony.
	FetchImage(context.Context, *FetchImageRequest) (*FetchImageResponse, error)
	ListImages(context.Context, *ListImagesRequest) (*ListImagesResponse, error)
	WithdrawImage(context.Context, *WithdrawImageRequest) (*WithdrawImageResponse, error)
	// Addresses that must never be written to again.
	// Whose correspondence the caller may open, for the supervisor view. A
	// separate surface from the personal mailbox on purpose: reading somebody
	// else's mail should be a deliberate act, not a wider default.
	ListSenders(context.Context, *ListSendersRequest) (*ListSendersResponse, error)
	ListSuppressions(context.Context, *ListSuppressionsRequest) (*ListSuppressionsResponse, error)
	AddSuppression(context.Context, *AddSuppressionRequest) (*AddSuppressionResponse, error)
	RemoveSuppression(context.Context, *RemoveSuppressionRequest) (*RemoveSuppressionResponse, error)
	// How this company reaches its mail host — the values off the provider's
	// admin console. Administrative: one setting for everybody.
	GetMailHost(context.Context, *GetMailHostRequest) (*GetMailHostResponse, error)
	SaveMailHost(context.Context, *SaveMailHostRequest) (*SaveMailHostResponse, error)
	// The caller's own mailbox. There is deliberately no employee_id on any of
	// these: nobody sets somebody else's authorisation code, administrators
	// included, because the only way to hold one is to have been given it by
	// the person it belongs to.
	GetMyMailAccount(context.Context, *GetMyMailAccountRequest) (*GetMyMailAccountResponse, error)
	// Records that a tracking pixel was fetched. Called by the gateway on
	// behalf of a recipient's mail client, which has no session.
	RecordOpen(context.Context, *RecordOpenRequest) (*RecordOpenResponse, error)
	// Proves the caller controls their mailbox by logging in to the mail host
	// with the code they typed, live. An ERP session alone must not open the
	// mailbox: this is what stands between a walked-away-from workstation and
	// somebody's correspondence.
	VerifyMailAccess(context.Context, *VerifyMailAccessRequest) (*VerifyMailAccessResponse, error)
	// Turns a Google authorisation code into a bound mailbox. The person
	// signed in on Google's own page; their password never existed here.
	CompleteGoogleOAuth(context.Context, *CompleteGoogleOAuthRequest) (*CompleteGoogleOAuthResponse, error)
	// Mail that arrived. A separate surface from the sent side because the two
	// have almost nothing in common: one is a delivery attempt with retries and
	// a provider verdict, the other is a document somebody sent us.
	ListInbound(context.Context, *ListInboundRequest) (*ListInboundResponse, error)
	// Search across every folder, rather than inside the one being viewed.
	SearchMail(context.Context, *SearchMailRequest) (*SearchMailResponse, error)
	GetInbound(context.Context, *GetInboundRequest) (*GetInboundResponse, error)
	// Turns either an explicitly selected part of this mail's text or one of
	// its stored attachments into a real Excel workbook. Exactly one source is
	// accepted. The source is resolved inside this service so a caller cannot
	// make the model read another employee's mail or an arbitrary object key.
	//
	// Enqueue only. There is deliberately no synchronous twin: the usage ledger
	// hangs off the job row, so a conversion that never becomes a job is a
	// conversion nobody is billed for. Anything that spends model tokens here
	// goes through a job, and the worker writes the token count whether the
	// model succeeds or fails.
	StartInboundExcelConversion(context.Context, *StartInboundExcelConversionRequest) (*StartInboundExcelConversionResponse, error)
	GetInboundExcelConversionJob(context.Context, *GetInboundExcelConversionJobRequest) (*GetInboundExcelConversionJobResponse, error)
	// 把一个办公文档附件转成 PDF 并返回可以直接显示的地址。第二次调用命中
	// 缓存，不再转换。
	PreviewInboundAttachment(context.Context, *PreviewInboundAttachmentRequest) (*PreviewInboundAttachmentResponse, error)
	// 把一封信的所有附件打成一个压缩包。响应里带着整个包的字节，所以网关那边
	// 的 gRPC 接收上限要跟着 MaxZipBytes 一起放宽。
	DownloadInboundAttachments(context.Context, *DownloadInboundAttachmentsRequest) (*DownloadInboundAttachmentsResponse, error)
	// ---- 自建文件夹（Issue #362）。文件夹真的建在邮件服务器上。 ----
	ListMailFolders(context.Context, *ListMailFoldersRequest) (*ListMailFoldersResponse, error)
	CreateMailFolder(context.Context, *CreateMailFolderRequest) (*CreateMailFolderResponse, error)
	RenameMailFolder(context.Context, *RenameMailFolderRequest) (*RenameMailFolderResponse, error)
	DeleteMailFolder(context.Context, *DeleteMailFolderRequest) (*DeleteMailFolderResponse, error)
	// 把一封信挪进某个自建文件夹；folder_id = 0 表示挪回收件箱。同步执行。
	MoveInbound(context.Context, *MoveInboundRequest) (*MoveInboundResponse, error)
	// One conversation, both directions, oldest first. Owner-scoped: the
	// caller sees only their own half of the world.
	GetMailThread(context.Context, *GetMailThreadRequest) (*GetMailThreadResponse, error)
	// 我名下的全部信箱，默认的排在最前。取代了「我的邮箱」那个单数答案：
	// 一个人可以绑多个，而按人取单行的查询会**随机**挑一个且不报错。
	ListMyMailboxes(context.Context, *ListMyMailboxesRequest) (*ListMyMailboxesResponse, error)
	// 换写信时默认用哪个信箱。清旧设新在一个事务里，中途不会出现零个或两个。
	SetDefaultMailbox(context.Context, *SetDefaultMailboxRequest) (*SetDefaultMailboxResponse, error)
	// 断开一个信箱：凭据清掉、不再收发，历史邮件原样留着。
	UnbindMailbox(context.Context, *UnbindMailboxRequest) (*UnbindMailboxResponse, error)
	// 智能转换的用量账（计量）：一个月一行，按人拆开，外加这家公司当下的
	// 额度状况。
	ExcelUsage(context.Context, *ExcelUsageRequest) (*ExcelUsageResponse, error)
	// 所有公司的额度和本月用量。**跨租户，平台运营专用。**
	ListExcelQuotas(context.Context, *ListExcelQuotasRequest) (*ListExcelQuotasResponse, error)
	// 给一家公司定每月上限，或恢复不限。**跨租户，平台运营专用。**
	SetExcelQuota(context.Context, *SetExcelQuotaRequest) (*SetExcelQuotaResponse, error)
	// One conversation as a document somebody outside the ERP can read: a
	// transcript, self-contained, nothing fetched when it is opened. Records
	// the export before returning the bytes — an export that cannot be logged
	// does not happen, which is the point of having the permission at all.
	ExportMailThread(context.Context, *ExportMailThreadRequest) (*ExportMailThreadResponse, error)
	// The export log. Scoped like the team mail view: a manager sees their own
	// team, an administrator sees the company.
	ListMailExports(context.Context, *ListMailExportsRequest) (*ListMailExportsResponse, error)
	// Inbox housekeeping: read/unread, star, archive, trash. Applied here
	// first and carried to the mail host within seconds by the write-back
	// queue, so the two views agree.
	MarkInbound(context.Context, *MarkInboundRequest) (*MarkInboundResponse, error)
	// Permanent deletion, from the trash only: removes the ERP-side record,
	// the raw MIME and the attachment copies in object storage, and the mail
	// host's own copy with them. Irreversible on both sides, deliberately.
	PurgeInbound(context.Context, *PurgeInboundRequest) (*PurgeInboundResponse, error)
	// Marks everything one view shows as read. Scoped to that view and never
	// the whole mailbox; the host is told too, like every other flag change.
	MarkViewRead(context.Context, *MarkViewReadRequest) (*MarkViewReadResponse, error)
	// Permanent deletion of everything in the trash at once. Trash also clears
	// itself after thirty days; this is the same thing done deliberately.
	EmptyTrash(context.Context, *EmptyTrashRequest) (*EmptyTrashResponse, error)
	// Clears the junk view into the trash. Not permanent deletion: the mail
	// worth finding in a spam folder is the enquiry the filter got wrong, and
	// that is noticed a day later, not now.
	EmptyJunk(context.Context, *EmptyJunkRequest) (*EmptyJunkResponse, error)
	// Mail this mailbox sent — through any client, over whatever history the
	// backfill has reached. ERP sends live in ListMessages with per-recipient
	// status; these are plain copies from the host's own Sent folder.
	ListMailboxSent(context.Context, *ListMailboxSentRequest) (*ListMailboxSentResponse, error)
	// Pull now rather than waiting for the next poll. A mail host offers no
	// webhook, so this is the "refresh" a person reaches for.
	SyncMailbox(context.Context, *SyncMailboxRequest) (*SyncMailboxResponse, error)
	mustEmbedUnimplementedEmailServiceServer()
}

